//! CLDR currency data (symbols, display names, fraction digits).
//!
//! The table is generated by tools/unicode/format/generate_misc.py from the
//! CLDR locale currency blocks and supplemental fraction digits.

const std = @import("std");

const blob = @embedFile("currencies_data.bin");

const header_len = 24;
const locale_count = readU16(8);
const currency_count = readU16(10);
const entry_count = readU32(12);
const string_length = readU32(16);

const code_offset = header_len;
const locale_offset = code_offset + @as(usize, currency_count) * 8;
const entry_offset = locale_offset + @as(usize, locale_count) * 12;
const strings_offset = entry_offset + @as(usize, entry_count) * 32;

comptime {
    if (blob.len < header_len or !std.mem.eql(u8, blob[0..4], "CJGD") or
        blob[4] != 1)
    {
        @compileError("invalid currency data");
    }
    if (strings_offset + @as(usize, string_length) != blob.len) {
        @compileError("invalid currency data lengths");
    }
}

pub const Entry = struct {
    symbol: []const u8,
    names: [6][]const u8,
};

fn readU16(offset: usize) u16 {
    return std.mem.readInt(u16, blob[offset..][0..2], .little);
}

fn readU32(offset: usize) u32 {
    return std.mem.readInt(u32, blob[offset..][0..4], .little);
}

fn strAt(offset: u32) []const u8 {
    if (offset == 0) return "";
    return std.mem.sliceTo(blob[strings_offset + @as(usize, offset) ..], 0);
}

fn codeAt(index: usize) []const u8 {
    return strAt(readU32(code_offset + index * 8));
}

fn codeIndex(code: []const u8) ?usize {
    var low: usize = 0;
    var high: usize = currency_count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        switch (std.mem.order(u8, codeAt(middle), code)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return middle,
        }
    }
    return null;
}

/// CLDR fraction digits for a currency code (defaults to 2).
pub fn fractionDigits(code: []const u8) u8 {
    const index = codeIndex(code) orelse return 2;
    return blob[code_offset + index * 8 + 4];
}

fn localeId(index: usize) []const u8 {
    const base = locale_offset + index * 12;
    const id_offset = readU32(base);
    const id_length = blob[base + 4];
    return blob[strings_offset + @as(usize, id_offset) ..][0..id_length];
}

fn findLocaleRecord(locale_name: []const u8) ?usize {
    var low: usize = 0;
    var high: usize = locale_count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        switch (std.mem.order(u8, localeId(middle), locale_name)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return middle,
        }
    }
    return null;
}

fn lookup(locale_name: []const u8, code: []const u8) ?Entry {
    const currency = codeIndex(code) orelse return null;
    var locale_index = findLocaleRecord(locale_name);
    if (locale_index == null) {
        if (std.mem.indexOfAny(u8, locale_name, "-_")) |position| {
            locale_index = findLocaleRecord(locale_name[0..position]);
        }
    }
    const record_index = locale_index orelse
        findLocaleRecord("en") orelse return null;
    const base = locale_offset + record_index * 12;
    var low: usize = readU16(base + 6);
    var high: usize = low + readU16(base + 8);
    while (low < high) {
        const middle = low + (high - low) / 2;
        const entry_base = entry_offset + middle * 32;
        const index = readU16(entry_base);
        if (index < currency) {
            low = middle + 1;
        } else if (index > currency) {
            high = middle;
        } else {
            var names: [6][]const u8 = undefined;
            for (0..6) |name_index| {
                names[name_index] = strAt(readU32(entry_base + 8 + name_index * 4));
            }
            return .{
                .symbol = strAt(readU32(entry_base + 4)),
                .names = names,
            };
        }
    }
    return null;
}

/// Localized symbol and display names for a currency, or null when the
/// locale has no data for it.
pub fn find(locale_name: []const u8, code: []const u8) ?Entry {
    return lookup(locale_name, code);
}

test "currency data" {
    const testing = @import("std").testing;
    try testing.expectEqual(@as(u8, 2), fractionDigits("USD"));
    try testing.expectEqual(@as(u8, 0), fractionDigits("JPY"));
    try testing.expectEqual(@as(u8, 3), fractionDigits("BHD"));
    const usd = find("en", "USD").?;
    try testing.expectEqualStrings("$", usd.symbol);
    try testing.expectEqualStrings("US dollars", usd.names[5]);
    const afn = find("fr", "AFN");
    try testing.expect(afn != null);
    try testing.expectEqualStrings("", afn.?.symbol);
    try testing.expectEqualStrings("afghanis afghan", afn.?.names[5]);
}
